const j = $json;
const texto = String(j.texto || '').slice(0, 4000);
const mensajesUsuario = (Array.isArray(j.historial) ? j.historial : []).filter(m => String(m.role) === 'user');
const extraerId = valor => {
  const contenido = String(valor || '').slice(0, 4000);
  const etiquetado = contenido.match(/\b(?:tracking\s*(?:id)?|n[úu]mero\s+de\s+seguimiento|seguimiento|gu[ií]a|paquete|pedido|env[ií]o)\b\D{0,35}(\d{5,12})\b/i);
  if (etiquetado) return etiquetado[1];
  const aislado = contenido.match(/^\s*(\d{5,12})\s*$/);
  return aislado ? aislado[1] : '';
};
const idActual = extraerId(texto);
const idPrevio = [...mensajesUsuario].reverse().map(m => extraerId(m.content)).find(Boolean) || '';
const paqueteId = idActual || idPrevio;
const patronEvidencia = /\b(evidencia|evidencias|foto|fotos|fotograf[ií]a|imagen|comprobante|constancia|acuse|prueba\s+de\s+entrega)\b/i;
const ultimoMensajeUsuario = mensajesUsuario.at(-1)?.content || '';
const solicitaEvidencia = patronEvidencia.test(texto) || (Boolean(idActual) && patronEvidencia.test(String(ultimoMensajeUsuario)));
const consultaPaquete = Boolean(idActual) || /\b(paquete|pedido|env[ií]o|gu[ií]a|tracking|seguimiento|estado|entrega|entregado|demora|retraso|evidencia|foto|fotograf[ií]a|comprobante)\b/i.test(texto);
const idsPermitidos = [...(Array.isArray(j.paquetes) ? j.paquetes.map(x => String(x.IdPaquete || '')) : []), paqueteId].filter(Boolean);
const limpiar = valor => String(valor || '').slice(0, 1500).replace(/https?:\/\/\S+/gi, '[enlace omitido]').replace(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/g, '[correo omitido]').replace(/\+?\d[\d\s().-]{7,}\d/g, numero => idsPermitidos.includes(numero.replace(/\D/g, '')) ? numero : '[teléfono omitido]');
const textoModelo = limpiar(texto);
const historialModelo = (Array.isArray(j.historial) ? j.historial : []).slice(-8).filter(m => ['user','assistant'].includes(String(m.role))).map(m => ({ role: String(m.role), content: limpiar(m.content) }));
const sellerId = Number(j.sellerId);
const sinVincular = j.sinVincular === true && j.ok === true && j.estado === 'pendiente' && (j.sellerId === null || j.sellerId === undefined);
const valido = sinVincular || (j.ok === true && !j.omitido && Number.isSafeInteger(sellerId) && sellerId > 0 && Boolean(texto));
return { eventId: String(j.eventoId || ''), conversacionId: String(j.conversacionId || ''), sellerId: sinVincular ? 0 : (valido ? sellerId : 0), texto, textoModelo, historialModelo, paqueteId: paqueteId ? Number(paqueteId) : null, solicitaEvidencia, consultaPaquete, valido, sinVincular, omitido: j.omitido === true, forzarDerivacion: !['text','button','interactive'].includes(String(j.tipoContenido || '')), tipoContenido: String(j.tipoContenido || '') };

const ctx = $('Validar contexto y extraer ID').itemMatching(0).json;
let filas = [];
try { const valor = $input.first().json.PaquetesJson; filas = Array.isArray(valor) ? valor : JSON.parse(String(valor || '[]')); } catch {}
const paquetes = filas.filter(x => Number.isFinite(Number(x.IdPaquete)) && Number(x.IdPaquete) > 0).slice(0, 30).map(x => ({ id: String(x.IdPaquete), estado: String(x.Estado || 'Estado no informado').slice(0, 120), fechaProgramada: x.FechaProgramada || null, fechaCambioEstado: x.FechaCambioEstado || null, visitado: x.Visitado === true || x.Visitado === 1 }));
const paqueteNoEncontrado = Boolean(ctx.paqueteId) && !paquetes.some(p => p.id === String(ctx.paqueteId));
const filaPaqueteSolicitado = ctx.paqueteId ? filas.find(x => String(x.IdPaquete) === String(ctx.paqueteId)) : null;
const paqueteConsultado = filaPaqueteSolicitado ? { id: String(filaPaqueteSolicitado.IdPaquete), estado: String(filaPaqueteSolicitado.Estado || 'Estado no informado').slice(0, 120), fechaEntrega: String(filaPaqueteSolicitado.FechaEntrega || '').slice(0, 10) || null, nombreRecibe: String(filaPaqueteSolicitado.NombreRecibe || '').trim().slice(0, 150) || null } : null;
const resumenPaquete = ctx.consultaPaquete && paqueteConsultado ? `Estado: ${paqueteConsultado.estado}\nDía de entrega: ${paqueteConsultado.fechaEntrega || 'Sin registrar'}\nQuién recibió: ${paqueteConsultado.nombreRecibe || 'Sin registrar'}` : '';
const evidenciaFila = ctx.solicitaEvidencia && ctx.paqueteId ? filas.find(x => String(x.IdPaquete) === String(ctx.paqueteId)) : null;
const evidenciaCandidata = String(evidenciaFila?.EvidenciaUrl || '').trim();
const hostSeguro = /^https:\/\/files\.rapiboy\.com(?:[/?#]|$)/i.test(evidenciaCandidata);
const caracteresSeguros = !/[\s\\\u0000-\u001f\u007f]/.test(evidenciaCandidata) && !/%0[ad]/i.test(evidenciaCandidata);
const evidenciaUrl = evidenciaCandidata.length > 0 && evidenciaCandidata.length <= 2048 && hostSeguro && caracteresSeguros ? evidenciaCandidata : null;
const evidenciaConId = Boolean(ctx.solicitaEvidencia && ctx.paqueteId);
const evidenciaNoDisponible = Boolean(evidenciaConId && !paqueteNoEncontrado && !evidenciaUrl);
return [{ json: { ...ctx, paquetes, paqueteConsultado, resumenPaquete, paqueteNoEncontrado, evidenciaUrl, evidenciaConId, evidenciaNoDisponible } }];

